/**
 * The registry: the reviewed data that places IDX-IC sub-industries, their
 * example companies and the links between them in the world
 * (docs/world/PRD-kawasan-industri.md §8.1). The constants that carry this
 * shape are GENERATED by scripts/world/build-registry.ts from the committed
 * source files under docs/world/sources/; nothing here is edited by hand.
 */

export const ZONES = [
  'ring-geological',
  'ring-biological',
  'estate-primary',
  'estate-manufacturing',
  'estate-utilities',
  'estate-operator',
  'estate-warehousing',
  'gateway',
  'town-distribution',
  'town-retail',
  'town-services',
  'town-health',
  'town-business',
  'town-financial',
  'infrastructure',
  'recovery',
  'unplaced',
] as const;
export type Zone = (typeof ZONES)[number];

export const CHAIN_STAGES = ['origins', 'processing', 'manufacturing', 'distribution', 'use-recovery', 'enabling'] as const;
export type ChainStage = (typeof CHAIN_STAGES)[number];

export const ARCHETYPES = ['PROC', 'DIST', 'ASSET', 'MINE', 'FARM', 'SERVICE'] as const;
export type Archetype = (typeof ARCHETYPES)[number];

/** One building family per zone (PRD §7.6); the builders take the family as a parameter. */
export const BUILDING_FAMILIES = [
  'pit', 'well-pad', 'quarry', 'stockpile', 'plantation-block', 'field', 'pond', 'forest-block',
  'process-plant', 'factory', 'packaging-plant', 'power-plant', 'water-plant', 'warehouse', 'cold-store',
  'operator-office', 'quay', 'apron', 'interchange', 'rail-yard', '3pl-shed', 'depot', 'market-hall',
  'supermarket', 'minimarket', 'department-store', 'shop', 'dealership', 'hotel', 'restaurant', 'cinema',
  'school', 'hospital', 'clinic', 'lab', 'office-tower', 'bank-tower', 'exchange', 'recycling-plant',
  'scrap-yard', 'compost-site', 'telecom-tower', 'construction-site', 'think-tank',
] as const;
export type BuildingFamily = (typeof BUILDING_FAMILIES)[number];

export type ListedCount = { n: number; source: string; asOf: string } | { n: null; note: 'not yet counted' };

export type ReviewState = 'owner' | 'proposed';

export interface CompanyRef {
  ticker: string;
  name: string;
  status: 'confirmed' | 'proposed';
  placeOverride?: { zone: Zone; reason: string };
  /** Why this company was proposed for the pair. */
  reason?: string;
  /** Where its listing in this sub-industry was checked. */
  source?: string;
  /** What the company does (PRD v2 §4.1): one factual line, present tense, no figures, no market data, no person's name. */
  does?: string;
  /** Where the line was drawn from: the issuer's own description, or the draft's note for the owner's review. */
  doesSource?: string;
}

export interface SubIndustry {
  /** Official IDX-IC sub-industry code, from the cited IDX document. */
  code: string;
  /** Indonesian name as IDX publishes it. */
  nameId: string;
  /** English name as IDX publishes it. */
  nameEn: string;
  sector: { code: string; name: string };
  subSector: { code: string; name: string };
  industry: { code: string; name: string };
  zone: Zone;
  buildingFamily: BuildingFamily;
  chainStage: ChainStage;
  /** Id in src/data/industryChain.ts (a stage, node or band). */
  chainNodeId: string;
  listed: ListedCount;
  /** Usually two. */
  companies: CompanyRef[];
  archetypeFallback: Archetype;
  review: { placedBy: ReviewState; note?: string };
}

export interface Measured {
  value: number;
  unit: string;
  source: string;
  period: string;
}

/**
 * What a link carries (PRD v2 §4.1, Appendix A), which decides the vehicle that runs it: bulk by dump truck or hopper,
 * liquid by tanker, cold by reefer, boxed by box truck or container trailer, parcel by van, people by bus; none draws
 * no vehicle (money and information move as coins and pulses).
 */
export const GOODS = ['bulk', 'liquid', 'cold', 'boxed', 'parcel', 'people', 'none'] as const;
export type Goods = (typeof GOODS)[number];

export interface Link {
  /** Sub-industry code of the supplier. */
  from: string;
  /** Sub-industry code of the customer. */
  to: string;
  /** What moves along the link (PRD v2 Appendix A). */
  goods: Goods;
  costShare?: Measured;
  demandShare?: Measured;
  intensity?: Measured;
  state: 'measured' | 'expected';
  note?: string;
}

/** A story (PRD v2 §3.10, Appendix B): a curated chain the visitor lights end to end and can ride. The owner's. */
export interface Story {
  id: string;
  title: string;
  /** One line, present tense, no figure. */
  standfirst: string;
  /** Sub-industry codes in reading order, each placed in the world. */
  hops: readonly string[];
  /** The goods class of each hop, one fewer than the codes. */
  goods: readonly Goods[];
  /** The lens the story reads best at. */
  lens: 'economy' | 'finance';
  /** Downstream reads with the goods; upstream against them, as money (Appendix B, 6). */
  direction: 'downstream' | 'upstream';
  /** Codes lit beside the hops: the banks that fund each step. */
  with: readonly string[];
}

export interface Room {
  id: string;
  label: string;
  /** essays.section the room lists, or null for a room fed by tags alone. */
  section: string | null;
  /** Rooms are switchable in the registry (PRD §7.10); the default two are on. */
  on: boolean;
}

export interface Registry {
  subIndustries: readonly SubIndustry[];
  links: readonly Link[];
  rooms: readonly Room[];
  /** The source citation the generator was locked to. */
  source: { title: string; publisher: string; url: string; sha256: string };
}
